// Claude's review tests for A13 (templates in a fixed body). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern: string, body: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method: 'ANY',
    urlPattern,
    response: { status: 200, headers: { 'content-type': 'application/json' }, body, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'default',
    scenarios: [{
      id: 'default',
      name: 'Default',
      mocks: [
        mock('filled', '/api/users/:id', '{"id":"{{params.id}}","page":"{{query.page}}","who":"{{headers.x-user}}","name":"{{body.name}}"}', { templates: true }),
        mock('literal', '/api/raw', '{"id":"{{params.id}}"}'),
      ],
    }],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

test('fetch and XHR get a filled body; a mock with templates off is sent as written', async () => {
  const { page, panel } = await open();
  try {
    const got = await page.evaluate(async () => {
      const f = await (await fetch('/api/users/7?page=2', { method: 'POST', headers: { 'X-User': 'anna' }, body: '{"name":"Anna"}' })).text();
      const x = await new Promise<string>((resolve) => {
        const r = new XMLHttpRequest();
        r.open('POST', '/api/users/8?page=3');
        r.setRequestHeader('x-user', 'bob');
        r.onload = () => resolve(r.responseText);
        r.send('{"name":"Bob"}');
      });
      const raw = await (await fetch('/api/raw')).text();
      return { f, x, raw };
    });
    expect(got).toEqual({
      f: '{"id":"7","page":"2","who":"anna","name":"Anna"}',
      x: '{"id":"8","page":"3","who":"bob","name":"Bob"}',
      raw: '{"id":"{{params.id}}"}',
    });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the editor has a Fill templates switch: on for a new mock, off for one without it', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'literal' }).click();
    await expect(panel.getByTestId('field-templates')).not.toBeChecked();
    await panel.getByTestId('field-templates').check();
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[1]!.templates).toBe(true);

    await panel.getByTestId('mock-new').click();
    await expect(panel.getByTestId('field-pattern')).toHaveValue('/');
    await expect(panel.getByTestId('field-templates')).toBeChecked();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[2]?.templates).toBe(true);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the switch is hidden for code replies', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'filled' }).click();
    await expect(panel.getByTestId('field-templates')).toBeVisible();
    await panel.getByTestId('reply-code').click();
    await expect(panel.getByTestId('field-templates')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Test bar shows the filled body', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('test-method').selectOption('POST');
    await panel.getByTestId('test-url').fill('/api/users/42?page=9');
    await panel.getByTestId('test-body').fill('{"name":"Cy"}');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-body-out')).toContainText('{"id":"42","page":"9","who":"","name":"Cy"}');
  } finally {
    await panel.close();
    await page.close();
  }
});
